import random
from dataclasses import dataclass, field


CURA_POCAO = 30
TABELA_LOOT = [("moeda", 60), ("poção", 30), ("espada", 10)]
PESOS = {"moeda": 0, "poção": 1, "espada": 8}


@dataclass
class Personagem:
    nome: str
    vida_max: int
    ataque: int
    defesa: int
    nivel: int = 1
    xp: int = 0
    vida: int = field(init=False)

    def __post_init__(self):
        self.vida = self.vida_max

    def esta_vivo(self) -> bool:
        return self.vida > 0

    def receber_dano(self, qtd: int) -> int:
        antes = self.vida
        self.vida = max(0, self.vida - qtd)
        return antes - self.vida

    def curar(self, qtd: int) -> int:
        antes = self.vida
        self.vida = min(self.vida_max, self.vida + qtd)
        return self.vida - antes


def calcular_dano(ataque: int, defesa: int, rng, chance_critico: float = 0.1) -> int:
    dano = max(1, ataque - defesa)
    if rng.random() < chance_critico:
        dano *= 2
    return dano


class Inventario:
    def __init__(self, capacidade):
        self.capacidade = capacidade
        self._quantidades = {}  # nome -> quantidade
        self._pesos = {}        # nome -> peso de uma unidade

    def quantidade(self, nome):
        return self._quantidades.get(nome, 0)

    def peso_total(self):
        return sum(self._pesos[nome] * qtd for nome, qtd in self._quantidades.items())

    def adicionar(self, nome, peso, qtd=1):
        if self.peso_total() + peso * qtd > self.capacidade:
            return False
        self._quantidades[nome] = self.quantidade(nome) + qtd
        self._pesos[nome] = peso
        return True

    def remover(self, nome, qtd=1):
        if self.quantidade(nome) < qtd:
            raise ValueError(f"não há {qtd} de {nome} no inventário")
        self._quantidades[nome] -= qtd
        if self._quantidades[nome] == 0:
            del self._quantidades[nome]

    def conteudo(self):
        return dict(self._quantidades)


def sortear(tabela, rng):
    total = sum(peso for _, peso in tabela)
    if total == 0:
        raise ValueError("a tabela de loot precisa de pelo menos um peso positivo")
    alvo = rng.random() * total
    acumulado = 0
    for item, peso in tabela:
        acumulado += peso
        if alvo < acumulado:
            return item


def xp_para_subir(nivel: int) -> int:
    return 100 * nivel


def ganhar_xp(p: Personagem, qtd: int) -> int:
    p.xp += qtd
    niveis = 0
    while p.xp >= xp_para_subir(p.nivel):
        p.xp -= xp_para_subir(p.nivel)
        p.nivel += 1
        p.vida_max += 10
        p.ataque += 2
        p.defesa += 1
        p.vida = p.vida_max
        niveis += 1
    return niveis


ONDAS = [
    [{"nome": "Slime", "vida": 12, "ataque": 5, "defesa": 0, "xp": 30}],
    [{"nome": "Lobo", "vida": 18, "ataque": 9, "defesa": 1, "xp": 45},
     {"nome": "Lobo", "vida": 18, "ataque": 9, "defesa": 1, "xp": 45}],
    [{"nome": "Ogro", "vida": 60, "ataque": 16, "defesa": 3, "xp": 90}],
]


def usar_pocao_se_precisar(heroi: Personagem, mochila: Inventario) -> bool:
    em_perigo = heroi.esta_vivo() and heroi.vida < 0.3 * heroi.vida_max
    if not em_perigo or mochila.quantidade("poção") == 0:
        return False
    mochila.remover("poção")
    heroi.curar(CURA_POCAO)
    return True


def lutar(heroi: Personagem, monstro: Personagem, mochila: Inventario, rng) -> bool:
    while True:
        usar_pocao_se_precisar(heroi, mochila)
        monstro.receber_dano(calcular_dano(heroi.ataque, monstro.defesa, rng))
        if not monstro.esta_vivo():
            return True
        heroi.receber_dano(calcular_dano(monstro.ataque, heroi.defesa, rng))
        if not heroi.esta_vivo():
            return False


def resumo(heroi: Personagem, mochila: Inventario, ondas_vencidas: int) -> dict:
    return {
        "ondas_vencidas": ondas_vencidas,
        "vivo": heroi.esta_vivo(),
        "nivel": heroi.nivel,
        "vida": heroi.vida,
        "itens": mochila.conteudo(),
    }


def rodar_arena(heroi: Personagem, mochila: Inventario, ondas: list, rng) -> dict:
    vencidas = 0
    for onda in ondas:
        for dados in onda:
            monstro = Personagem(dados["nome"], dados["vida"], dados["ataque"], dados["defesa"])
            if not lutar(heroi, monstro, mochila, rng):
                return resumo(heroi, mochila, vencidas)
            ganhar_xp(heroi, dados["xp"])
            item = sortear(TABELA_LOOT, rng)
            mochila.adicionar(item, PESOS[item])
        vencidas += 1
    return resumo(heroi, mochila, vencidas)


